let lang='en';try{lang=localStorage.getItem('kajicho-language-20261017')||'en';}catch{}if(!copy[lang])lang='en';
function node(tag,text,cls){const el=document.createElement(tag);if(text!==undefined)el.textContent=text;if(cls)el.className=cls;return el;}
function anchor(text,href,cls){const el=node('a',text,cls);el.href=href;return el;}
function section(title,id,number){const el=node('section',undefined,'team-section');if(id)el.id=id;el.append(node('p',number,'eyebrow'),node('h2',title));return el;}
function render(){
 const t=copy[lang];
 document.documentElement.lang={zh:'zh-CN',en:'en',ja:'ja'}[lang];
 document.querySelectorAll('[data-team-t]').forEach(el=>el.textContent=t[el.dataset.teamT]);
 document.querySelectorAll('[data-team-banner]').forEach(el=>{const cfd=el.dataset.teamBanner==='cfd',p=node('p');p.append(node('strong',t[cfd?'cfdBanner':'banner']),document.createTextNode(t[cfd?'cfdBannerText':'bannerText']));el.replaceChildren(p,anchor(t.nav+' →','team.html'));});
 const mount=document.getElementById('team-content');if(!mount)return;
 document.title='KAJICHO / '+t.nav;
 document.querySelectorAll('[data-lang]').forEach(b=>{b.classList.toggle('active',b.dataset.lang===lang);b.setAttribute('aria-pressed',String(b.dataset.lang===lang));});
 const hero=node('section',undefined,'team-hero');hero.append(node('p','TEAM START / 2026-10-20','eyebrow'),node('h1',t.title),node('p',t.intro));
 const actions=node('div',undefined,'team-actions');actions.append(anchor(t.guide,links.guide,'team-button primary'),anchor(t.repo,repo,'team-button'),anchor(t.plan,links.plan,'team-button'));hero.append(actions);const download=node('div',undefined,'team-download');download.append(anchor(downloadCopy[lang][0],packageUrl,'team-button primary'),node('p',downloadCopy[lang][1]),anchor(downloadCopy[lang][2],"https://github.com/Urshuaige/Urban-Design-Studio-2026-Kajicho/archive/refs/heads/main.zip",'team-button'));download.append(anchor({zh:'查看当前场地图集',en:'Explore current site maps',ja:'現在の地図を見る'}[lang],"index.html#mapping",'team-button'));hero.append(download);
 const state=node('section',undefined,'team-status');for(const [title,text] of [[t.ready,t.readyText],[t.paused,t.pausedText]]){const div=node('div');div.append(node('h2',title),node('p',text));state.append(div);}
 const work=section(t.workTitle,'work','01 / WORK');const grid=node('div',undefined,'team-work');for(const [title,text] of t.work){const article=node('article');article.append(node('h3',title),node('p',text));grid.append(article);}work.append(grid);
 const start=section(t.stepsTitle,'start','02 / FIRST VISIT');const steps=node('ol',undefined,'team-steps');for(const [title,text] of t.steps){const item=node('li');item.append(node('h3',title),node('p',text));steps.append(item);}start.append(steps);
 const resources=section(t.dataTitle,'resources','03 / MATERIALS');const wrap=node('div',undefined,'team-table-wrap'),table=node('table',undefined,'team-table'),head=node('thead'),tr=node('tr');for(const title of t.columns){const th=node('th',title);th.scope='col';tr.append(th);}head.append(tr);const body=node('tbody');for(const row of t.rows){const tr=node('tr');row.forEach((text,i)=>{const cell=node(i===0?'th':'td',text);if(i===0)cell.scope='row';tr.append(cell);});body.append(tr);}table.append(head,body);wrap.append(table);resources.append(wrap);
 const dataLinks=node('div',undefined,'team-links');for(const key of ['manifest','tasks','data','access'])dataLinks.append(anchor(t[key],links[key]));resources.append(dataLinks,node('p',t.scope,'team-note'));
 const open=section(t.openTitle,'choices','04 / TEAM CHOICES');const openGrid=node('div',undefined,'team-open');for(const rows of [t.open,t.methods]){const ul=node('ul');rows.forEach(text=>ul.append(node('li',text)));openGrid.append(ul);}const openLinks=node('div',undefined,'team-links');openLinks.append(anchor(t.meeting,links.meeting),anchor(t.status,links.status));open.append(openGrid,openLinks);
 const footer=node('footer');footer.append(node('span',t.footer),anchor(downloadCopy[lang][3],'index.html'));
 mount.replaceChildren(hero,state,work,start,resources,open,footer);
}
for(const button of document.querySelectorAll('[data-lang]'))button.addEventListener('click',()=>{const chosen=button.dataset.lang;if(!copy[chosen])return;lang=chosen;try{localStorage.setItem('kajicho-language-20261017',lang);}catch{}render();});
render();
